async function touchTicket(id,active) { state.touchQueue=state.touchQueue.catch(()=>{}).then(()=>api('/v1/asks/'+encodeURIComponent(id)+'/touch',{body:{active}}));return state.touchQueue; }
async function releaseTicket() { const id=state.activeTicket;state.activeTicket=null;state.ticketActive=false;if(id)try{await touchTicket(id,false);}catch{/* Session loss and expiry do not expose ticket internals. */} }
