  const body=ticket.body||{},request=body.request||{};append(target,keyValues([['Platform',ticket.platform||body.platform],['Account',body.alias],['Scope',ticket.scope||body.scope],['Action',request.operation||request.tool],['Destination',request.url||body.quote_url||body.merchant],['Recipient',request.to||request.recipient],['Subject',request.subject],['Content',request.body||request.text],['Purpose',body.purpose],['Maximum payment',body.ceiling_usd!==undefined?money(body.ceiling_usd):body.amount!==undefined?money(body.amount):null]]));const ref=node('details',null,'advanced-options');append(ref,node('summary','Exact action reference'),node('p',ticket.action_hash||ticket.action_id||ticket.ticket_id,'run-id'),node('h3','Full requested action'),node('pre',JSON.stringify(body,null,2),'exact-action'));target.append(ref);const reasonLabel=node('label','Reason for the recorded decision (optional)'),reason=node('textarea');reason.rows=2;reason.maxLength=2000;reasonLabel.append(reason);
