function connectionList(value) { return Array.isArray(value?.connections)?value.connections:[]; }
function currentConnection() { return connectionList(harness($('#run-harness').value)).find(item=>item.id===$('#run-mode').value); }
function modelRow() { return (currentConnection()?.models||[]).find(row=>row.id===$('#run-model').value); }
function perMillion(row) { return row.priced?'$'+Number(row.input_usd)+' in · $'+Number(row.output_usd)+' out per MTok':'no reviewed price'; }
function modelOption(row,estimated) { const option=node('option',row.label+(row.label===row.id?'':' ('+row.id+')')+' · '+perMillion(row)+(row.selectable&&estimated?' · estimated':'')+(row.served===false?' · not served by this key':''));option.value=row.id;option.disabled=!row.selectable;return option; }
function updateRunOptions(resetModel=true) { const value=harness($('#run-harness').value),previous=$('#run-mode').value,hosted=!!value?.hosts?.length;$('#assay-options').hidden=!hosted;$('#assay-note').hidden=!hosted;$('#run-host').replaceChildren(...(value?.hosts||[]).map(id=>{const option=node('option',harness(id)?.name||id);option.value=id;return option;}));$('#run-mode').replaceChildren();for(const connection of connectionList(value)){const option=node('option',connection.label+(connection.ready?'':' · set up on Harnesses'));option.value=connection.id;option.selected=connection.id===previous;$('#run-mode').append(option);}updateRunMode(resetModel); }
function updateRunMode(resetModel=true) { const connection=currentConnection(),rows=connection?.models||[],estimated=connection?.billing?.kind==='estimated',previous=$('#run-model').value;$('#run-model').replaceChildren();for(const [group,label] of [['current','Current'],['earlier','Earlier']]){const members=rows.filter(row=>(row.group==='current')===(group==='current'));if(!members.length)continue;const optgroup=node('optgroup');optgroup.label=label;optgroup.append(...members.map(row=>modelOption(row,estimated)));$('#run-model').append(optgroup);}const selectable=rows.filter(row=>row.selectable),preferred=settingsValues().default_model,recommended=harness($('#run-harness').value)?.recommended_model,choice=(!resetModel&&selectable.find(row=>row.id===previous))||selectable.find(row=>row.id===preferred)||selectable.find(row=>row.id===recommended)||selectable.find(row=>row.group==='current')||selectable[0];if(choice)$('#run-model').value=choice.id;$('#run-readiness').textContent=connection?.ready?'Connection ready. Nothing beams down until you press Beam down.':connection?.reason||'Choose and connect a harness on the Harnesses page first.';$('#run-setup').hidden=!!connection?.ready;$('#run-budget-label').textContent=connection?.id==='subscription'?'World tools limit (USD)':'World budget (USD)';$('#run-billing-note').textContent=connection?.id!=='subscription'?'Model API usage and world tools are debited from the world budget.':estimated?'Model use is estimated from the session’s own usage reports at API prices; your plan’s own limits also apply.':'Your provider subscription pays for model usage; its own plan limits still apply. Model dollars are not measured here. This world limit covers separately metered tools.';updateEffort();updateShape(); }
function updateEffort() { const row=modelRow(),select=$('#run-effort'),previous=select.value;select.replaceChildren();if(!row?.efforts?.length){const option=node('option','Not adjustable for this model');option.value='';select.append(option);select.disabled=true;checkModel();return;}select.disabled=false;const automatic=node('option','Model default ('+row.default_effort+')');automatic.value='';select.append(automatic);for(const level of row.efforts){const option=node('option',level);option.value=level;select.append(option);}select.value=row.efforts.includes(previous)?previous:'';checkModel(); }
function checkModel() { const connection=currentConnection(),row=modelRow(),note=$('#model-note'),ok=!!row?.selectable;note.textContent=!row?'This connection offers no model it can run yet.':!ok?(row.served===false?row.label+' is not served by this key.':row.label+' has no reviewed price, so its spend cannot be metered or estimated. Choose a priced model, or add its rates to the world’s price table.'):row.label+' · '+perMillion(row)+(connection?.billing?.kind==='estimated'?' · spend estimated from the session’s own usage reports at these prices.':'.');note.classList.toggle('field-error',!ok);$('#launch-button').disabled=!ok||!connection?.ready;return ok; }
function hostedChoice() { return $('#assay-options').hidden?{}:{host:$('#run-host').value,actions:Number($('#run-actions').value)}; }
function isLife() { return $('#shape-life').checked&&!$('#shape-life').disabled; }
function updateShape() { const value=harness($('#run-harness').value),subscription=$('#run-mode').value==='subscription',estimable=!!value?.transcript;$('#shape-life').disabled=subscription&&!estimable;if($('#shape-life').disabled&&$('#shape-life').checked){$('#shape-run').checked=true;state.shapeForced=true;}else if(!$('#shape-life').disabled&&state.shapeForced){$('#shape-life').checked=true;state.shapeForced=false;}const life=isLife(),estimated=life&&subscription;$('#shape-note').textContent=!subscription?'':!estimable?'A '+(value?.name||'this harness')+' life needs an API key: its subscription stream reports usage only when a session ends, so a balance could not stop it in time.':estimated?'With a subscription, the balance is estimated from the session’s own usage reports at API prices; your plan’s own limits also apply.':'';$('#run-budget-label').textContent=life?'Starting balance (USD)':subscription?'World tools limit (USD)':'World budget (USD)';$('#run-wall-label').textContent=life?'Session length (minutes)':'Time limit (minutes)';$('#earn-options').hidden=!life;$('#objective-help').textContent=life?'With an objective, the party can claim it is achieved; your confirmation ends the life.':'';if(estimated)$('#run-billing-note').textContent='Model use is estimated from the session’s own usage reports at API prices and paid from its balance, with world tools. When the balance can’t cover another message, the life is stranded until a deposit arrives. Low money never ends it.';else if(life)$('#run-billing-note').textContent='Model API usage and world tools are paid from its balance. When the balance can’t cover a model call, the life is stranded until a deposit arrives. Low money never ends it.';checkModel(); }
async function openRun(harnessId,authMode) { if(!state.authenticated)return;$('#run-form-error').textContent='';const defaults=settingsValues();$('#run-harness').replaceChildren();for(const value of state.harnesses){const option=node('option',value.name||value.id);option.value=value.id;option.selected=value.id===(harnessId||defaults.default_harness_id);$('#run-harness').append(option);}$('#run-budget').value=String(defaults.default_budget_usd??20);$('#run-wall').value=String(defaults.default_wall_minutes??120);$('#run-goal').value='';$('#objective-toggle').open=false;$('#shape-life').disabled=false;$('#shape-life').checked=true;state.shapeForced=false;$('#new-run-form').elements.market.checked=false;$('#new-run-form').elements.bounty.checked=false;updateRunOptions();if(authMode){$('#run-mode').value=authMode;updateRunMode();}if(!state.harnesses.length){$('#run-readiness').textContent='No harness is available yet. Open Harnesses to install and connect one.';$('#launch-button').disabled=true;}$('#new-run-dialog').showModal(); }

$('#new-run-form').addEventListener('submit',event=>{event.preventDefault();guard(async()=>{const button=$('#launch-button');button.disabled=true;$('#run-form-error').textContent='';try{const form=event.currentTarget,data=new FormData(form);const packs=['deliver','footprint'];if(data.has('belief'))packs.push('belief');if(data.has('forecast'))packs.push('forecast');if(data.has('watch'))packs.push('watch');if(isLife()){const result=await api('/api/lives',{body:{harness_id:String(data.get('harness_id')),auth_mode:String(data.get('auth_mode')),model:String(data.get('model')||'').trim(),effort:String(data.get('effort')||'')||null,...hostedChoice(),objective:String(data.get('goal')||'').trim()||null,balance_usd:Number(data.get('budget_usd')),session_minutes:Number(data.get('wall_minutes')),reply_policy:String(data.get('reply_policy')),packs,bounty:data.has('bounty'),market:data.has('market')},timeout:60000});state.selectedLife=result.life?.life_id||null;$('#new-run-dialog').close();notify('Energized. The party is beaming down; its first session is opening.');navigateLife(state.selectedLife);await refreshWorkspace();return;}const result=await api('/api/runs',{body:{harness_id:String(data.get('harness_id')),auth_mode:String(data.get('auth_mode')),model:String(data.get('model')||'').trim(),effort:String(data.get('effort')||'')||null,...hostedChoice(),goal:String(data.get('goal')||'').trim()||null,budget_usd:Number(data.get('budget_usd')),wall_minutes:Number(data.get('wall_minutes')),reply_policy:String(data.get('reply_policy')),packs},timeout:60000});state.selected=result.run_id||result.run?.run_id;$('#new-run-dialog').close();notify('Energized. The run is beaming down; its actual startup state appears in the ship’s log.');navigate('runs',state.selected);await refreshWorkspace();}catch(error){if(error.auth)throw error;$('#run-form-error').textContent=error.message;}finally{button.disabled=false;}});});
$('#stop-form').addEventListener('submit',event=>{event.preventDefault();guard(async()=>{const target=event.currentTarget.querySelector('[type=submit]');target.disabled=true;try{await api('/api/runs/'+encodeURIComponent(state.selected)+'/stop',{body:{},timeout:60000});$('#stop-dialog').close();notify('Requested. Follow the state while ongoing work is drained and sealed.');await refreshWorkspace();}catch(error){if(error.auth)throw error;$('#stop-error').textContent=error.message;}finally{target.disabled=false;}});});
$('#beam-form').addEventListener('submit',event=>{event.preventDefault();guard(async()=>{const target=event.currentTarget.querySelector('[type=submit]');target.disabled=true;try{await api('/api/lives/'+encodeURIComponent(state.selectedLife)+'/beam-up',{body:{},timeout:60000});$('#beam-dialog').close();notify('Beamed up. The life has ended; its record stays.');await refreshWorkspace();}catch(error){if(error.auth)throw error;$('#beam-error').textContent=error.message;}finally{target.disabled=false;}});});
for(const input of document.querySelectorAll('input[name=shape]'))input.addEventListener('change',()=>{state.shapeForced=false;updateShape();});
$('#login-form').addEventListener('submit',async event=>{event.preventDefault();const input=$('#operator-token'),token=input.value;input.value='';const submit=event.currentTarget.querySelector('[type=submit]');submit.disabled=true;$('#login-error').textContent='';try{const result=await api('/api/session',{body:{token}});if(!result.authenticated)throw new Error('Not authenticated');state.authenticated=true;state.requiresToken=!!result.requires_token;$('#login-dialog').close();$('#session-label').textContent='Operator connected';$('#session-button').classList.add('connected');$('#session-button').setAttribute('aria-label',state.requiresToken?'Sign out of operator workspace':'Local operator access');await refreshWorkspace();}catch{$('#login-error').textContent='The operator token was not accepted. Check it and try again.';}finally{input.value='';submit.disabled=false;}});
$('#login-dialog').addEventListener('cancel',event=>{if(!state.authenticated)event.preventDefault();});
$('#session-button').addEventListener('click',()=>guard(async()=>{if(!state.authenticated){$('#login-dialog').showModal();return;}if(!state.requiresToken){notify('This local instance does not require an operator token.');return;}await api('/api/session',{method:'DELETE'});authLost();}));
$('#run-harness').addEventListener('change',()=>updateRunOptions());$('#run-model').addEventListener('change',updateEffort);$('#run-mode').addEventListener('change',()=>updateRunMode());
$('#run-setup').addEventListener('click',()=>{$('#new-run-dialog').close();navigate('harnesses');});
$('#new-run-top').addEventListener('click',()=>guard(openRun));$('#refresh-button').addEventListener('click',()=>guard(refreshWorkspace));for(const item of document.querySelectorAll('[data-page]'))item.addEventListener('click',()=>navigate(item.dataset.page));for(const item of document.querySelectorAll('[data-close]'))item.addEventListener('click',()=>$('#'+item.dataset.close).close());
$('#ask-dialog').addEventListener('close',()=>{releaseTicket();});
function markActivity(){if(!state.activeTicket)return;state.lastActivity=Date.now();if(document.visibilityState==='visible'&&document.hasFocus()&&(!state.ticketActive||Date.now()-state.lastTouch>10000)){state.ticketActive=true;state.lastTouch=Date.now();touchTicket(state.activeTicket,true).catch(()=>{});}}
for(const name of ['pointerdown','keydown','touchstart'])document.addEventListener(name,markActivity,{passive:true});
function visibility() { if(!state.activeTicket)return;const active=document.visibilityState==='visible'&&document.hasFocus()&&Date.now()-state.lastActivity<30000;state.ticketActive=active;state.lastTouch=Date.now();touchTicket(state.activeTicket,active).catch(()=>{}); }
window.addEventListener('focus',visibility);window.addEventListener('blur',visibility);document.addEventListener('visibilitychange',visibility);window.addEventListener('hashchange',readLocation);
window.addEventListener('pagehide',()=>{if(state.activeTicket)fetch('/v1/asks/'+encodeURIComponent(state.activeTicket)+'/touch',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({active:false}),keepalive:true}).catch(()=>{});$('#operator-token').value='';for(const input of document.querySelectorAll('input[type=password]'))input.value='';});
setInterval(()=>{if(!state.activeTicket)return;const active=document.visibilityState==='visible'&&document.hasFocus()&&Date.now()-state.lastActivity<30000;if(active||state.ticketActive){state.ticketActive=active;state.lastTouch=Date.now();touchTicket(state.activeTicket,active).catch(()=>{});}},10000);
setInterval(()=>{if(!state.authenticated||state.refreshing||document.visibilityState!=='visible'||document.querySelector('dialog[open]'))return;guard(async()=>{if(state.page==='harnesses'){if(document.activeElement?.matches('input,textarea,select'))return;for(const [id,auth] of state.connections)if(['connecting','awaiting_code'].includes(auth.state)){const result=await api('/api/harnesses/'+encodeURIComponent(id)+'/connection');state.connections.set(id,result.connection||result);}const catalog=await api('/api/harnesses');state.harnesses=catalog.harnesses||[];renderHarnesses();return;}if(state.page==='settings'||state.page==='beliefs')return;if(state.page==='runs'&&document.activeElement?.matches('input,textarea,select'))return;const [runs,lives]=await Promise.all([api('/api/runs'),api('/api/lives')]);state.runs=runs.runs||[];state.lives=Array.isArray(lives.lives)?lives.lives:[];updateBadges();await loadPage(true);});},5000);

async function boot() { readLocation();try{const session=await api('/api/session');state.requiresToken=!!session.requires_token;if(!session.authenticated){authLost();return;}state.authenticated=true;$('#session-label').textContent=session.requires_token?'Operator connected':'Local instance';$('#session-button').classList.add('connected');$('#session-button').setAttribute('aria-label',state.requiresToken?'Sign out of operator workspace':'Local operator access');await refreshWorkspace();}catch(error){if(!error.auth){content(empty('Your world is not reachable',error.message,button('Try again',boot,'button primary')));$('#sync-state').textContent='Connection unavailable';}} }
boot();
